page_data_script:
name = frappe.form_dict.name

order = frappe.call("webshop.webshop.api.get_order_info", name=name)

data.order = order

data.is_logged_in = frappe.user != "Guest"
data.can_access_cart = False
data.page_data = {
    "url": frappe.get_url(),
    "doc": {
        "name": order["doc"].name,
        "doctype" : order["doc"].doctype
    }
}

current_user = frappe.session.user
url = frappe.get_url();
data.page_data = {
    "url": url,
}
items = frappe.call("webshop.webshop.api.get_wishlist_items")
for item in items:
    item.route = f"/item/{item['website_item']}"

data.items = items

data.is_logged_in = frappe.user != "Guest"
data.can_access_cart = frappe.call("webshop.webshop.shopping_cart.cart.can_access_cart") and frappe.user != "Guest"


data.page_data = {
    "url": frappe.get_url()
}
